script=r'''import sqlite3,re,itertools
c=sqlite3.connect("'''+p+r'''")
sid='f571c237-1cd9-4292-8dfc-cf7671fc072b'
msg=c.execute("select content from messages where session_id=? and role='user' order by id limit 2 offset 1",(sid,)).fetchone()[0]
# Actually rows: get demo message id=3
msg=c.execute("select content from messages where id=3").fetchone()[0]
def section(label, nrows):
    t=msg.split(label+':\n',1)[1].split('\n\n',1)[0]
    return [list(map(int,re.findall(r'\d+',line))) for line in t.splitlines()[:nrows]]
grid=section('Demo pair 1 input (15x27)',15); out=section('Demo pair 1 output (15x13)',15)
L={(y,x) for y in range(15) for x in range(13) if grid[y][x]==5}
R={(y,x) for y in range(15) for x in range(13) if grid[y][x+14]==8}
O={(y,x) for y in range(15) for x in range(13) if out[y][x]==2}
print('sizes',len(L),len(R),len(O),'dims',len(grid),len(grid[0]),len(out),len(out[0]))
print('O', [sorted(x for yy,x in O if yy==y) for y in range(15)])
print('direct diffs',len(O^(L|R)),len(O^(L^R)),len(O^(L&R)))
H,W=15,13
ops={'OR':lambda a,b:a|b,'XOR':lambda a,b:a^b,'AND':lambda a,b:a&b}
orient={'id':lambda y,x:(y,x),'lr':lambda y,x:(y,W-1-x),'ud':lambda y,x:(H-1-y,x),'180':lambda y,x:(H-1-y,W-1-x)}
def candidates(S,wrap):
  res=[]
  for oname,f in orient.items():
    base={f(y,x) for y,x in S}
    for dy in range(-14,15):
      for dx in range(-12,13):
        T=set()
        for y,x in base:
          yy,xx=y+dy,x+dx
          if wrap: yy%=H;xx%=W
          if 0<=yy<H and 0<=xx<W:T.add((yy,xx))
        mask=sum(1<<(y*W+x) for y,x in T)
        res.append((mask,(oname,dy,dx)))
  return res
om=sum(1<<(y*W+x) for y,x in O)
for wrap in [False,True]:
  CL,CR=candidates(L,wrap),candidates(R,wrap)
  print('wrap',wrap,'candidate counts',len(CL),len(CR))
  for opname,fn in ops.items():
    best=(999,None)
    for ml,tl in CL:
      for mr,tr in CR:
        d=(fn(ml,mr)^om).bit_count()
        if d<best[0]:best=(d,(tl,tr))
    print(opname,best)
  for name,C in [('L',CL),('R',CR)]:
    best=min(((m^om).bit_count(),t) for m,t in C)
    print(name,'single best',best)
'''
