import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/H0-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u008/system/state/hermes/state.db'; c=sqlite3.connect(p); sid='f571c237-1cd9-4292-8dfc-cf7671fc072b'
for n in (2,3,4):
 s=c.execute('select content from messages where session_id=? and content like ?',(sid,f'%Demo pair {n} input%')).fetchone()[0]
 m=re.search(rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \((\d+)x(\d+)\):\n(.*?)(?:\n\nSame instance|\Z)',s,re.S)
 H,W,ib,OH,OW,ob=m.groups(); H,W,OH,OW=map(int,(H,W,OH,OW))
 parse=lambda t:[[int(x) for x in line.split()] for line in t.strip().splitlines()]
 g,o=parse(ib),parse(ob); sep=OW; L=[row[:sep] for row in g]; R=[row[sep+1:] for row in g]
 from collections import Counter
 bg=Counter(x for row in o for x in row).most_common(1)[0][0]; om={(r,j) for r in range(OH) for j in range(OW) if o[r][j]!=bg}
 eq={(r,j) for r in range(H) for j in range(OW) if L[r][j]==R[r][j]}
 print('demo',n,'sep',sep,'dividervals',sorted({row[sep] for row in g}),'L/R palettes',sorted(set(sum(L,[]))),sorted(set(sum(R,[]))),'out',Counter(x for row in o for x in row),'equals',len(eq),'marks',len(om),'mismatch',sorted(om^eq))
 if n==2: print('mark/equal coords',sorted(om),sorted(eq))

import sqlite3,re
c=sqlite3.connect('/home/USER/continual-arc-baselines/.workbench/stage1/H0-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u008/system/state/hermes/state.db');sid='f571c237-1cd9-4292-8dfc-cf7671fc072b'
txt='\n'.join(x[0] or '' for x in c.execute('select content from messages where session_id=? order by id',(sid,)))
blocks=re.findall(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|$)',txt,re.S)
print('demos',len(blocks))
for n,h,w,ins,oh,ow,outs in blocks:
 I=[[int(x) for x in l.split()] for l in ins.strip().splitlines()]; O=[[int(x) for x in l.split()] for l in outs.strip().splitlines()]
 sep=next(j for j in range(len(I[0])) if len({row[j] for row in I})==1)
 A=[r[:sep] for r in I];B=[r[sep+1:] for r in I]
 from collections import Counter
 mode=lambda g:Counter(x for row in g for x in row).most_common(1)[0][0]
 print('\nDEMO',n,'dims',len(I),len(I[0]),'sep',sep,I[0][sep],'widths',len(A[0]),len(B[0]),'modes',mode(A),mode(B),mode(O),'colors',set(sum(A,[])),set(sum(B,[])),set(sum(O,[])))
 for r in range(len(O)):
  def fg(v, panel): return {j for j,x in enumerate(panel[r]) if x!=mode(panel)}
  l=fg(0,A); rr=fg(0,B); om={j for j,x in enumerate(O[r]) if x!=mode(O)}
  eq={j for j,(x,y) in enumerate(zip(A[r],B[r])) if x==y}
  ne={j for j,(x,y) in enumerate(zip(A[r],B[r])) if x!=y}
  # displayed compressed all sets
  print(r,'L',sorted(l),'R',sorted(rr),'O',sorted(om),'eq',sorted(eq),'ne',sorted(ne))

